// Parity: the browser layer A model must compute exactly what pipeline/lr/features.py + train.py
// computed. Vectors are regenerated by `python pipeline/lr/train.py`.
import { describe, expect, it } from 'vitest';
import vectors from './fixtures/lr_vectors.json';
import { dense, hashedRow, scoreLayerALR } from '../src/checks/text/scorers/lr';

describe('layer A logistic regression parity', () => {
  for (const [i, v] of (vectors as { text: string; dense: number[]; hashed: Record<string, number>; prob: number }[]).entries()) {
    it(`vector ${i}`, () => {
      const d = dense(v.text);
      expect(d.length).toBe(v.dense.length);
      d.forEach((x, j) => expect(x).toBeCloseTo(v.dense[j], 9));
      const row = hashedRow(v.text);
      const want = Object.entries(v.hashed);
      expect(row.size).toBe(want.length);
      for (const [k, val] of want) expect(row.get(Number(k))).toBeCloseTo(val, 9);
      expect(scoreLayerALR(v.text)).toBeCloseTo(v.prob, 6);
    });
  }

  it('scores an obvious roundup above a casual human note', () => {
    const slop = "In today's fast-paced world, finding the perfect coffee grinder can be a game-changer. Whether you're a seasoned barista or a casual sipper, these versatile machines are ideal for anyone. Moreover, our top picks are easy to clean, durable, and offer great value for money. Let's dive into the comprehensive buying guide and elevate your morning ritual with a seamless experience.";
    const human = "Mine is four years old. The motor still runs but the hopper cracked last winter, so honestly I'd just buy the cheaper one again and keep the receipt this time. My brother has the expensive one and it jams twice a week!! Not worth it imo. Anyway the burrs on mine still cut fine, I just tape the crack.";
    expect(scoreLayerALR(slop)).toBeGreaterThan(scoreLayerALR(human));
  });
});
